#!/usr/bin/env bash
set -euo pipefail

OUTPUT_PATH="/tmp/openapi.json"
CI_TOKEN="${CI_TOKEN:-}"
if [[ -z "$CI_TOKEN" ]]; then
  echo "Error: CI_TOKEN environment variable is not set"
  exit 1
fi

curl -s -L -H "Authorization: Bearer ${CI_TOKEN}" \
     "https://cdn.example.com/specs/v2/openapi.json" -o "${OUTPUT_PATH}"
echo "OpenAPI spec downloaded to ${OUTPUT_PATH}"
$ echo "Done."
Done.
